import{_ as s,c as h,j as e,a as d,G as o,w as l,a2 as c,B as a,o as p}from"./chunks/framework.B-T05WX8.js";const y=JSON.parse('{"title":"移动端登录 · 使用与配置文档","description":"","frontmatter":{},"headers":[],"relativePath":"plugin/mobile-login.md","filePath":"plugin/mobile-login.md"}'),g={name:"plugin/mobile-login.md"};function b(u,t,q,m,x,k){const r=a("VPNolebaseInlineLinkPreview"),n=a("NolebaseGitContributors"),i=a("NolebaseGitChangelog");return p(),h("div",null,[t[8]||(t[8]=e("h1",{id:"移动端登录-·-使用与配置文档",tabindex:"-1"},[d("移动端登录 · 使用与配置文档 "),e("a",{class:"header-anchor",href:"#移动端登录-·-使用与配置文档","aria-label":'Permalink to "移动端登录 · 使用与配置文档"'},"​")],-1)),e("blockquote",null,[e("p",null,[t[1]||(t[1]=d("面向 ")),t[2]||(t[2]=e("strong",null,"站点管理员（Halo 站长）",-1)),t[3]||(t[3]=d("。App / 小程序端开发者请看 ")),o(r,{href:"./mobile-login-api.html"},{default:l(()=>t[0]||(t[0]=[d("《移动端登录 · 接口文档》")])),_:1}),t[4]||(t[4]=d("。"))]),t[5]||(t[5]=e("p",null,[d("适用插件版本："),e("strong",null,"uni-halo v3.0.0+"),d("，Halo："),e("strong",null,"2.26.0+")],-1))]),t[9]||(t[9]=c('<hr><h2 id="一、这个能力解决什么问题" tabindex="-1">一、这个能力解决什么问题 <a class="header-anchor" href="#一、这个能力解决什么问题" aria-label="Permalink to &quot;一、这个能力解决什么问题&quot;">​</a></h2><p>Halo 原生没有「第三方客户端登录」能力。Halo 的访问令牌（PAT）需要用户在后台手动创建，App 端无法自助获取。</p><p>本插件补上这一环：App 端调用插件接口完成登录，插件<strong>代用户签发一枚 Halo 原生 PAT</strong> 返回。该令牌与后台手动创建的令牌完全同构，可访问 Halo 原生 API 与插件接口。</p><p><strong>站长需要决定的只有三件事</strong>：</p><ol><li>开不开、开哪几种登录方式</li><li>登录后给移动端什么权限</li><li>微信小程序的密钥（如果要开微信登录）</li></ol><hr><h2 id="二、前置条件" tabindex="-1">二、前置条件 <a class="header-anchor" href="#二、前置条件" aria-label="Permalink to &quot;二、前置条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>Halo 版本</td><td><strong>2.26.0 及以上</strong>（依赖 <code>CryptoService</code> 提供的 PAT 签名能力）</td></tr><tr><td>插件版本</td><td>uni-halo v3.0.0+</td></tr><tr><td>HTTPS</td><td><strong>强烈建议</strong>。令牌以 Bearer 明文传输，HTTP 下等同公开密码</td></tr><tr><td>微信小程序</td><td>仅在使用微信登录时需要：已注册小程序、拿到 <strong>AppID</strong> 与 <strong>AppSecret</strong></td></tr></tbody></table><blockquote><p>Halo 版本不足时，登录能力会自动关闭。</p></blockquote><hr><h2 id="三、快速开始" tabindex="-1">三、快速开始 <a class="header-anchor" href="#三、快速开始" aria-label="Permalink to &quot;三、快速开始&quot;">​</a></h2><h3 id="第-1-步-开启登录能力" tabindex="-1">第 1 步：开启登录能力 <a class="header-anchor" href="#第-1-步-开启登录能力" aria-label="Permalink to &quot;第 1 步：开启登录能力&quot;">​</a></h3><p>进入 <strong>Halo 后台 → 插件 → UniHalo → 设置 → 移动端登录</strong>。</p><div class="tip custom-block"><p class="custom-block-title">截图占位</p><p>此处待补充：「设置 → 移动端登录」配置页截图。</p></div><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th><th>建议</th></tr></thead><tbody><tr><td>开启登录能力</td><td>总开关</td><td>先设为「开启」，其余配好后再回来确认</td></tr><tr><td>账号密码登录</td><td>使用 Halo 账号密码登录</td><td>建议开启</td></tr><tr><td>微信小程序一键登录</td><td>微信登录开关</td><td>需要微信小程序，否则关闭</td></tr><tr><td>自动注册用户名前缀</td><td>微信新用户的用户名前缀</td><td>默认 <code>unihalo</code>，见下方说明</td></tr></tbody></table><blockquote><p><strong>密码登录与微信登录是两条互相独立的能力</strong>，各自有开关，不存在从属关系。 微信一键登录固定为「已绑定则登录、未绑定则自动建号并登录」，没有「必须先注册」的中间态。</p></blockquote><p><strong>「自动注册用户名前缀」怎么设？</strong></p><p>首次登录的微信用户会自动创建 Halo 账号，用户名 = <strong>前缀 + 两位递增序号</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>unihalo01  unihalo02  unihalo03  ...  unihalo99  unihalo100</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table tabindex="0"><thead><tr><th>约束</th><th>说明</th></tr></thead><tbody><tr><td>字符</td><td>只允许小写字母、数字、连字符；不能以连字符开头或结尾</td></tr><tr><td>长度</td><td>前缀 + 两位序号后总长度需在 <strong>4–63</strong> 之间（Halo 限制），故前缀至少 2 位，建议 ≥3</td></tr><tr><td>不可改</td><td><strong>Halo 用户名创建后不可修改</strong>，请一次设好</td></tr></tbody></table><p>配套昵称同样带序号（<code>微信用户01</code>），便于在用户列表里区分。初始密码为随机强密码且不对外提供，这类账号通过微信登录使用。</p><blockquote><p>前缀非法时会自动回落到 <code>unihalo</code> 并在日志中告警，注册功能不会中断。</p></blockquote><h3 id="第-2-步-配置登录权限" tabindex="-1">第 2 步：配置登录权限 <a class="header-anchor" href="#第-2-步-配置登录权限" aria-label="Permalink to &quot;第 2 步：配置登录权限&quot;">​</a></h3><p>同页 <strong>登录权限</strong> 区域。</p><div class="tip custom-block"><p class="custom-block-title">截图占位</p><p>此处待补充：「登录权限」区域截图。</p></div><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th><th>默认</th></tr></thead><tbody><tr><td>权限策略</td><td><code>继承用户在 Halo 的角色</code> 或 <code>按下方配置裁剪</code></td><td>继承</td></tr><tr><td>登录后默认角色</td><td>裁剪模式下勾选的角色</td><td>已登录用户</td></tr><tr><td>令牌有效期（天）</td><td>登录令牌的有效天数</td><td>30</td></tr></tbody></table><p><strong>两种策略怎么选？</strong></p><table tabindex="0"><thead><tr><th>策略</th><th>行为</th><th>适用</th></tr></thead><tbody><tr><td><strong>继承</strong>（inherit）</td><td>令牌权限 = 该用户在 Halo 的全部角色权限</td><td>管理员自己用、信任的移动端；希望移动端与网页端权限一致</td></tr><tr><td><strong>裁剪</strong>（intersect）</td><td>令牌权限 = 勾选角色 ∩ 用户已有角色</td><td>公开站点，希望<strong>统一压低</strong>移动端权限上限</td></tr></tbody></table><p><strong>关键：两种策略都不会提权。</strong></p><p>裁剪模式是<strong>取交集</strong>，不是「赋予」。勾选「管理员」但用户本身是「投稿者」→ 最终只有投稿者权限。这保证移动端永远无法获得超过用户本人的权限。</p><p><strong>裁剪模式的常见坑</strong></p><p>自动注册的微信新用户在 Halo 里几乎没有角色，交集很可能是<strong>空</strong> → 登录后零权限，<code>permissions</code> 为 <code>[]</code>。</p><p>解决办法二选一：</p><ul><li>在「登录后默认角色」中<strong>保留「已登录用户」（<code>authenticated</code>）</strong> —— 这是 Halo 给所有登录用户的基础角色，新用户也有</li><li>或改用「继承」策略</li></ul><blockquote><p>「已登录用户」角色自带：读取自己资料、修改自己昵称/简介、上传头像、修改密码、管理自己的令牌等。用它兜底即可满足大多数移动端场景。</p></blockquote><h3 id="第-3-步-配置微信小程序密钥-仅微信登录需要" tabindex="-1">第 3 步：配置微信小程序密钥（仅微信登录需要） <a class="header-anchor" href="#第-3-步-配置微信小程序密钥-仅微信登录需要" aria-label="Permalink to &quot;第 3 步：配置微信小程序密钥（仅微信登录需要）&quot;">​</a></h3><ol><li>先开启「微信小程序一键登录」</li><li>点击 <strong>微信小程序密钥</strong> 选择器 → 新建密钥</li><li>填入两项：</li></ol><table tabindex="0"><thead><tr><th>Key</th><th>值</th><th>获取位置</th></tr></thead><tbody><tr><td><code>appId</code></td><td>小程序 AppID</td><td>微信公众平台 → 开发管理 → 开发设置</td></tr><tr><td><code>appSecret</code></td><td>小程序 AppSecret</td><td>同上（需管理员扫码，只显示一次，请立即保存）</td></tr></tbody></table><ol start="4"><li>保存设置</li></ol><div class="tip custom-block"><p class="custom-block-title">截图占位</p><p>此处待补充：「微信小程序密钥」新建与填写截图。</p></div><blockquote><p>密钥只保存在服务端，不会下发给客户端；请妥善保管 AppSecret，泄露后请在微信公众平台重置并回到此处更新。</p></blockquote><blockquote><p><strong>结论</strong>：安全边界是「Halo 的权限体系」，不是加密。因此<strong>不要给不可信的角色授予 Secret 读取权限</strong>，也不要把 Halo 管理员账号交给不信任的人。</p></blockquote><h3 id="第-4-步-配置小程序服务器域名" tabindex="-1">第 4 步：配置小程序服务器域名 <a class="header-anchor" href="#第-4-步-配置小程序服务器域名" aria-label="Permalink to &quot;第 4 步：配置小程序服务器域名&quot;">​</a></h3><p>在 <strong>微信公众平台 → 开发管理 → 开发设置 → 服务器域名 → request 合法域名</strong> 中加入你的站点域名：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://example.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p>必须是已备案域名 + 有效 HTTPS 证书，且<strong>不能带端口</strong>。微信小程序不支持 IP 和自定义端口。</p></blockquote><h3 id="第-5-步-验证" tabindex="-1">第 5 步：验证 <a class="header-anchor" href="#第-5-步-验证" aria-label="Permalink to &quot;第 5 步：验证&quot;">​</a></h3><ol><li>用 App / 小程序访问 <code>GET /apis/api.unihalo.ialley.cn/v1alpha1/plugins/uni-halo/getConfigs/loginConfig</code>，确认返回的三个开关与设置一致</li><li>走一次登录，确认能拿到 <code>token</code></li><li>带 <code>Authorization: Bearer &lt;token&gt;</code> 调一次 <code>GET .../auth/profile</code>，确认能拿到用户信息</li></ol><hr><h2 id="四、配置项速查表" tabindex="-1">四、配置项速查表 <a class="header-anchor" href="#四、配置项速查表" aria-label="Permalink to &quot;四、配置项速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>配置项</th><th>类型</th><th style="text-align:center;">默认</th><th style="text-align:center;">是否下发客户端</th></tr></thead><tbody><tr><td>登录方式</td><td>开启登录能力</td><td>单选</td><td style="text-align:center;">关闭</td><td style="text-align:center;">是</td></tr><tr><td>登录方式</td><td>账号密码登录</td><td>开关</td><td style="text-align:center;">开</td><td style="text-align:center;">是</td></tr><tr><td>登录方式</td><td>微信小程序一键登录</td><td>开关</td><td style="text-align:center;">关</td><td style="text-align:center;">是</td></tr><tr><td>登录方式</td><td>微信小程序密钥</td><td>Secret</td><td style="text-align:center;">空</td><td style="text-align:center;">否</td></tr><tr><td>登录方式</td><td>自动注册用户名前缀</td><td>文本</td><td style="text-align:center;">unihalo</td><td style="text-align:center;">否</td></tr><tr><td>登录权限</td><td>权限策略</td><td>下拉</td><td style="text-align:center;">继承</td><td style="text-align:center;">否</td></tr><tr><td>登录权限</td><td>登录后默认角色</td><td>多选</td><td style="text-align:center;">已登录用户</td><td style="text-align:center;">否</td></tr><tr><td>登录权限</td><td>令牌有效期（天）</td><td>数字</td><td style="text-align:center;">30</td><td style="text-align:center;">否</td></tr></tbody></table><hr><h2 id="五、令牌管理" tabindex="-1">五、令牌管理 <a class="header-anchor" href="#五、令牌管理" aria-label="Permalink to &quot;五、令牌管理&quot;">​</a></h2><h3 id="_5-1-令牌长什么样" tabindex="-1">5.1 令牌长什么样 <a class="header-anchor" href="#_5-1-令牌长什么样" aria-label="Permalink to &quot;5.1 令牌长什么样&quot;">​</a></h3><ul><li>插件签发的令牌以 <code>pat_</code> 开头，与你在 Halo 后台手动创建的个人令牌同等地位，可直接访问 Halo 原生 API 与插件全部接口</li></ul><h3 id="_5-2-在哪里能看到" tabindex="-1">5.2 在哪里能看到 <a class="header-anchor" href="#_5-2-在哪里能看到" aria-label="Permalink to &quot;5.2 在哪里能看到&quot;">​</a></h3><p><strong>Halo 后台 → 个人中心 → 个人令牌</strong>。插件签发的令牌与用户手动创建的混在一起展示，可通过名称区分：插件签发的形如 <code>pat-&lt;用户名&gt;-&lt;随机&gt;</code>。</p><h3 id="_5-3-过期与清理" tabindex="-1">5.3 过期与清理 <a class="header-anchor" href="#_5-3-过期与清理" aria-label="Permalink to &quot;5.3 过期与清理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>机制</th><th>说明</th></tr></thead><tbody><tr><td>自动失效</td><td>到达「令牌有效期」后自动失效，需重新登录</td></tr><tr><td>定时清理</td><td>插件会定期清理<strong>插件签发的</strong>已过期令牌</td></tr><tr><td>安全边界</td><td>绝不删除用户在后台手动创建的任何令牌</td></tr></tbody></table><blockquote><p>想立刻让某个令牌失效：在「个人令牌」页面删除，或让用户在 App 端登出（登出 = 吊销）。</p></blockquote><h3 id="_5-4-手动吊销" tabindex="-1">5.4 手动吊销 <a class="header-anchor" href="#_5-4-手动吊销" aria-label="Permalink to &quot;5.4 手动吊销&quot;">​</a></h3><p>用户在 App 端调 <code>/auth/logout</code> 即吊销当前令牌。管理员也可在后台「个人令牌」直接删除。</p><hr><h2 id="六、安全建议" tabindex="-1">六、安全建议 <a class="header-anchor" href="#六、安全建议" aria-label="Permalink to &quot;六、安全建议&quot;">​</a></h2><h3 id="_6-1-必须做" tabindex="-1">6.1 必须做 <a class="header-anchor" href="#_6-1-必须做" aria-label="Permalink to &quot;6.1 必须做&quot;">​</a></h3><ul><li><strong>启用 HTTPS</strong>。否则令牌等同明文密码，中间人可直接劫持</li><li><strong>裁剪模式保留 <code>authenticated</code></strong>，避免新用户零权限（见第 2 步的坑）</li><li><strong>确认「登录权限」里的默认角色包含 <code>authenticated</code></strong>，微信新用户零权限将无法使用任何功能</li></ul><h3 id="_6-2-强烈建议" tabindex="-1">6.2 强烈建议 <a class="header-anchor" href="#_6-2-强烈建议" aria-label="Permalink to &quot;6.2 强烈建议&quot;">​</a></h3><ul><li><strong>限制管理员数量</strong>。Secret 的保护依赖角色权限体系，管理员越多密钥暴露面越大</li><li><strong>定期轮换 AppSecret</strong>。在微信公众平台重置后，同步更新 Halo 里的 Secret</li><li><strong>公开站点用裁剪模式</strong>，把移动端权限压到最低可用集</li><li><strong>令牌有效期别设太长</strong>。30 天是平衡点；高安全场景建议 7 天</li></ul><h3 id="_6-3-已知风险-当前版本" tabindex="-1">6.3 已知风险（当前版本） <a class="header-anchor" href="#_6-3-已知风险-当前版本" aria-label="Permalink to &quot;6.3 已知风险（当前版本）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>风险</th><th>说明</th><th>缓解</th></tr></thead><tbody><tr><td><strong>签名私钥可读</strong></td><td>Halo 的 <code>CryptoService</code> 会返回含私钥的 JWK，理论上插件可伪造任意用户令牌</td><td>只安装可信插件；不要给不可信插件授权</td></tr><tr><td><strong>限流是单实例内存计数</strong></td><td>多实例部署时各算各的，且重启后计数清零</td><td>Halo 通常单实例部署；多实例场景请在网关层再叠加一层限流</td></tr></tbody></table><h3 id="_6-4-内置的登录限流" tabindex="-1">6.4 内置的登录限流 <a class="header-anchor" href="#_6-4-内置的登录限流" aria-label="Permalink to &quot;6.4 内置的登录限流&quot;">​</a></h3><p>密码登录已加入失败限流，防止暴力破解：</p><table tabindex="0"><thead><tr><th>维度</th><th>阈值</th><th>说明</th></tr></thead><tbody><tr><td>用户名</td><td>连续失败 <strong>5 次</strong></td><td>拦定向爆破；登录成功后立即清零</td></tr><tr><td>来源 IP</td><td>累计失败 <strong>20 次</strong></td><td>拦换着用户名扫号；刻意不在成功登录后清零</td></tr></tbody></table><p>命中后锁定 <strong>15 分钟</strong>，接口返回 <strong>429</strong> <code>TOO_MANY_ATTEMPTS</code>。窗口结束后计数自然作废，无需人工解锁。</p><blockquote><p>IP 取的是 <strong>TCP 源地址</strong>，不是 <code>X-Forwarded-For</code> —— 后者由客户端提供、可随意伪造，拿它做限流等于没做。反代部署时计到的是反代 IP，这是刻意的取舍。</p></blockquote><hr><h2 id="七、故障排查" tabindex="-1">七、故障排查 <a class="header-anchor" href="#七、故障排查" aria-label="Permalink to &quot;七、故障排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>处理</th></tr></thead><tbody><tr><td>所有登录返回 <code>LOGIN_DISABLED</code></td><td>总开关未开</td><td>设置页开启「开启登录能力」</td></tr><tr><td>密码登录返回 <code>PASSWORD_LOGIN_DISABLED</code></td><td>密码登录开关关了</td><td>打开开关</td></tr><tr><td>密码正确却返回 <code>BAD_CREDENTIALS</code></td><td>① 用了昵称而非用户名 ② 账号开启了 2FA</td><td>用 Halo 用户名登录；2FA 账号改微信登录</td></tr><tr><td>微信登录返回 <code>WECHAT_LOGIN_FAILED</code></td><td>① code 已用过 ② AppSecret 错误 ③ 域名未配置</td><td>重新 <code>wx.login()</code>；核对 Secret；检查小程序服务器域名</td></tr><tr><td>微信登录返回 <code>REGISTER_FAILED</code></td><td>序号连续被占用（极端并发）</td><td>重试一次即可；持续出现请查看插件日志</td></tr><tr><td>密码登录返回 429 <code>TOO_MANY_ATTEMPTS</code></td><td>该用户名或来源 IP 触发限流</td><td>等待 15 分钟窗口自然结束；确认不是有人在爆破</td></tr><tr><td>带 token 请求返回 401 <code>UNAUTHENTICATED</code></td><td>① 令牌过期 ② 令牌被吊销 ③ Header 格式错</td><td>检查 <code>Bearer </code> 后是否有空格；重新登录</td></tr><tr><td>登录后 <code>permissions</code> 为空数组</td><td>裁剪模式下用户无对应角色</td><td>在默认角色中补上 <code>authenticated</code>（见第 2 步）</td></tr><tr><td><code>getConfigs</code> 里没有 <code>loginConfig</code></td><td>设置页从未保存过该分组</td><td>进设置页保存一次</td></tr><tr><td>微信登录提示「密钥资源不存在」</td><td>Secret 被删除但设置项还留着名字</td><td>重新选择/创建密钥</td></tr></tbody></table><h3 id="查看日志" tabindex="-1">查看日志 <a class="header-anchor" href="#查看日志" aria-label="Permalink to &quot;查看日志&quot;">​</a></h3><p>插件日志中会记录微信 <code>code2Session</code> 的 <strong>errcode</strong>（不记录响应体，避免泄露敏感信息）。日志级别 <code>WARN</code> 及以上的认证失败都会留痕。</p><hr><h2 id="八、常见问题" tabindex="-1">八、常见问题 <a class="header-anchor" href="#八、常见问题" aria-label="Permalink to &quot;八、常见问题&quot;">​</a></h2><p><strong>Q：令牌和 Halo 后台手动创建的 PAT 有什么区别？</strong></p><p>A：没有本质区别，都能访问 Halo API。唯一区别是插件签发的令牌会被插件<strong>定时清理</strong>（过期后自动移除），而手动创建的令牌一直保留、由你自己管理。</p><p><strong>Q：可以限制某个用户不能登录移动端吗？</strong></p><p>A：可以。在 Halo 后台把该用户<strong>禁用</strong>，密码登录与微信登录都会返回 <code>USER_DISABLED</code>。两种登录方式对禁用状态的处理是一致的。</p><p><strong>Q：AppSecret 会被写进日志吗？</strong></p><p>A：不会。微信接口的响应体从不落日志，只记录 <code>errcode</code>。</p><p><strong>Q：换域名 / 换服务器后需要重新配置吗？</strong></p><p>A：需要更新微信公众平台的 request 合法域名。Halo 侧无需改动（密钥存在 Halo 里，与域名无关）。</p><p><strong>Q：令牌能不能手动延长？</strong></p><p>A：不能。到期后必须重新登录。这是刻意设计 —— 无状态的短生命周期令牌比可续期的更安全。</p><p><strong>Q：移动端能改昵称头像吗？</strong></p><p>A：<strong>当前版本不能。</strong> 微信自动注册的用户停留在默认昵称（<code>微信用户01</code> 这种带序号的形式）与无头像状态。这是已知缺口，见下方路线图。</p><blockquote><p>补充：<code>UserReconciler</code> 会在用户没有头像附件时强制清空 <code>spec.avatar</code>，所以<strong>无法</strong>通过预设一个默认头像 URL 来解决，只能由客户端本地占位。</p></blockquote><hr><h2 id="九、路线图" tabindex="-1">九、路线图 <a class="header-anchor" href="#九、路线图" aria-label="Permalink to &quot;九、路线图&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">优先级</th><th>项</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;">P1</td><td>资料更新接口</td><td><code>PUT /auth/profile</code>（昵称/简介）+ <code>POST /auth/avatar</code>（头像上传，落 Halo 附件系统）</td></tr><tr><td style="text-align:center;">P2</td><td>令牌续期</td><td>临近过期时无感刷新</td></tr><tr><td style="text-align:center;">P2</td><td>登录审计日志</td><td>记录登录 IP、设备、时间</td></tr></tbody></table><p><strong>已完成</strong>：</p><ul><li>禁用用户对微信登录生效（此前禁用状态只拦密码登录，是安全漏洞）</li><li>登录失败限流（用户名 5 次 / IP 20 次，15 分钟窗口，返回 429）</li><li><code>/auth/profile</code> 改为只读，不再重复签发令牌</li></ul><hr><h2 id="十、微信绑定管理" tabindex="-1">十、微信绑定管理 <a class="header-anchor" href="#十、微信绑定管理" aria-label="Permalink to &quot;十、微信绑定管理&quot;">​</a></h2><p>插件通过 Halo 的 <code>user:detail:tabs:create</code> 扩展点，在<strong>原生用户详情页</strong>加了一个「微信绑定」选项卡：</p><ul><li>查看该用户是否已绑定微信、绑定的微信标识（openid / unionid）、绑定时间</li><li>一键<strong>解绑</strong>（只删绑定关系，<strong>不删 Halo 用户</strong>，用户可重新绑定或改用密码登录）</li></ul><blockquote><p>Halo 原生只提供「用户中心 → 账号绑定」这种<strong>自己解绑自己</strong>的入口，Console 侧没有全量绑定关系的管理界面，这个选项卡补的正是管理员视角。</p><p>注意：Halo 的<strong>用户列表</strong>没有提供显示字段扩展点（<code>user:list-item:field:create</code> 不存在），所以无法在列表里加一列「是否微信用户」的标记。需要批量筛选时，可在列表搜索框输入用户名前缀（如 <code>unihalo</code>）筛出自动注册的微信用户。</p></blockquote><hr><h2 id="十一、相关文档" tabindex="-1">十一、相关文档 <a class="header-anchor" href="#十一、相关文档" aria-label="Permalink to &quot;十一、相关文档&quot;">​</a></h2>',108)),e("ul",null,[e("li",null,[o(r,{href:"./mobile-login-api.html"},{default:l(()=>t[6]||(t[6]=[d("移动端登录 · 接口文档")])),_:1}),t[7]||(t[7]=d(" —— App 端对接"))])]),o(n),o(i)])}const A=s(g,[["render",b]]);export{y as __pageData,A as default};
